      "number": 1,
      "arFull": "تَبٰرَكَ الَّذِیْ نَزَّلَ الْفُرْقَانَ عَلٰی عَبْدِهٖ لِیَكُوْنَ لِلْعٰلَمِیْنَ نَذِیْرَا ۟ۙ",
