      "en": "Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -",
      "footnotesUr": "[1] فرقان کے معنی ہیں حق وباطل، توحید وشرک اور عدل وظلم کے درمیان فرق کرنے والا، اس قرآن نے کھول کر ان امور کی وضاحت کردی ہے، اس لئے اسے فرقان سے تعبیر کیا۔\n[2] اس سے بھی معلوم ہوا کہ نبی کریم (صلى الله عليه وسلم) کی نبوت عالم گیر ہے اور آپ تمام انسانوں اور جنوں کے لئے ہادی ورہنما بنا کر بھیجے گئے ہیں۔ جس طرح دوسرے مقام پر فرمایا «قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا» (الأعراف - 158) اور حدیث میں بھی فرمایا «بُعِثْتُ إِلَى الأَحْمَرِ وَالأَسْوَدِ» (صحيح مسلم، كتاب المساجد) «كَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ عَامَّةً» (صحيح بخاري، كتاب التيمم ومسلم كتاب المساجد) ”مجھے احمر واسود سب کی طرف نبی بنا کر بھیجا گیا ہے۔ پہلے نبی کسی ایک قوم کی طرف معبوث ہوتا تھا اور میں تمام لوگوں کی طرف نبی بنا کر بھیجا گیا ہوں“۔ رسالت ونبوت کے بعد، توحید کا بیان کیا جا رہا ہے۔ یہاں اللہ کی چار صفات بیان کی گئی ہیں۔",
