      "number": 4,
      "arFull": "وَقَالَ الَّذِیْنَ كَفَرُوْۤا اِنْ هٰذَاۤ اِلَّاۤ اِفْكُ فْتَرٰىهُ وَاَعَانَهٗ عَلَیْهِ قَوْمٌ اٰخَرُوْنَ ۛۚ فَقَدْ جَآءُوْ ظُلْمًا وَّزُوْرًا ۟ۚۛ",
      "ur": "اور کافروں نے کہا یہ تو بس خود اسی کا گھڑا گھڑایا جھوٹ ہے جس پر اور لوگوں نے بھی اس کی مدد کی[1] ہے، دراصل یہ کافر بڑے ہی ﻇلم اور سرتاسر جھوٹ کے مرتکب ہوئے ہیں.",
      "en": "And those who disbelieve say, \"This [Qur’ān] is not except a falsehood he invented, and another people assisted him in it.\" But they have committed an injustice and a lie.",
      "footnotesUr": "[1] مشرکین کہتے تھے کہ محمد ( (صلى الله عليه وسلم) ) نے یہ کتاب گھڑنے میں یہود سے یا ان کے بعض موالی (مثلاً ابوفکیہہ یسار، عداس اور جبروغیرہم) سے مدد لی ہے۔ جیسا کہ سورۃ النحل، آیت 103 میں اس کی ضروری تفصیل گزرچکی ہے۔ یہاں قرآن نے اس الزام کو ظلم اور جھوٹ سے تعبیر کیا ہے، بھلا ایک امی شخص دوسروں کی مدد سے ایسی کتاب پیش کر سکتا ہے جو فصاحت و بلاغت اور اعجاز کلام میں بےمثال ہو، حقائق ومعارف بیانی میں بھی معجزنگار ہو، انسانی زندگی کے لئے احکام وقوانین کی تفصیلات میں بھی لاجواب ہو اور اخبار ماضیہ اور مستقبل میں وقوع پذیر ہونے والے واقعات کی نشاندہی اور وضاحت میں بھی اس کی صداقت مسلم ہو۔",
