      "ur": "اللہ تعالیٰ تو ایسا بابرکت ہے کہ اگر چاہے تو آپ کو بہت سے ایسے باغات عنایت فرما دے جو ان کے کہے ہوئے باغ سے بہت ہی بہتر ہوں جن کے نیچے نہریں لہریں لے رہی ہوں اور آپ کو بہت سے (پختہ) محل بھی دے دے.[1]",
