      "footnotesUr": "[1] بعض نے اس سے یہ استدلال بھی کیا ہےکہ اہل ایمان کے لیے قیامت کا یہ ہولناک دن اتنا مختصر اوران کا حساب اتنا آسان ہوگا کہ قیلولے کے وقت تک یہ فارغ ہوجائیں گے اورجنت میں یہ اپنے اہل خاندان اور حورعین کےساتھ دوپہر کو استراحت فرما ہوں گے، جس طرح حدیث میں ہے کہ مومن کے لیے یہ دن اتنا ہلکا ہوگا کہ جتنے میں دنیا میں ایک فرض نماز ادا کرلینا۔ (مسند احمد 4 / 75)",
