      "number": 31,
      "arFull": "وَكَذٰلِكَ جَعَلْنَا لِكُلِّ نَبِیٍّ عَدُوًّا مِّنَ الْمُجْرِمِیْنَ ؕ وَكَفٰی بِرَبِّكَ هَادِیًا وَّنَصِیْرًا ۟",
      "ur": "اور اسی طرح ہم نے ہر نبی کے دشمن بعض گناه گاروں کو بنادیا ہے[1] اور تیرا رب ہی ہدایت کرنے واﻻ اور مدد کرنے واﻻ کافی ہے.[2]",
      "en": "And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.",
      "footnotesUr": "[1] یعنی جس طرح اے محمد! (صلى الله عليه وسلم) تیری قوم میں سے وہ لوگ تیرے دشمن ہیں جنہوں نے قرآن کو چھوڑ دیا، اسی طرح گزشتہ امتوں میں بھی تھا، یعنی ہر نبی کے دشمن وہ لوگ ہوتے تھے جو گناہ گار تھے، وہ لوگوں کو گمراہی کی طرف بلاتے تھے سورۃ الانعام آیت 112 میں بھی یہ مضمون بیان کیاگیا ہے۔\n[2] یعنی یہ کافر گو لوگوں کو اللہ کے راستے سے روکتے ہیں لیکن تیرا رب جس کو ہدایت دے، اس کو ہدایت سے کون روک سکتا ہے؟ اصل ہادی اور مددگار تو تیرا رب ہی ہے۔",
