      "en": "And it is He who has created from water [i.e., semen] a human being and made him [a relative by] lineage and marriage. And ever is your Lord competent [concerning creation].",
      "footnotesUr": "[1] نسب سےمراد وہ رشتے داریاں ہیں جو باپ یا ماں کی طرف سے ہوں اورصھر سے مراد وہ قرابت مندی ہے جو شادی کے بعد بیوی کی طرف سے ہو، جس کو ہماری زبان میں سسرالی رشتے کہا جاتا ہے۔ ان دونوں رشتے داریوں کی تفصیل آیت حُرِّمَتْ عَلَيْكُمْ (النساء۔ 23) اور«وَلا تَنْكِحُوا مَا نَكَحَ آبَاؤُكُمْ» (النساء ۔ 23) میں بیان کردی گئی ہے۔ اور رضاعی رشتے داریاں حدیث کی رو سے نسبی رشتوں میں شامل ہے۔ جیسا کہ فرمایا «يَحْرُمُ مِنَ الرَّضَاِع مَا يَحْرُمُ مِنَ النَّسَبِ»(البخاري ـ نمبر 2645 - ومسلم، نمبر 1070)۔",
