      "en": "Blessed is He who has placed in the sky great stars and placed therein a [burning] lamp and luminous moon.",
      "footnotesUr": "[1] بُرُوجٌ بُرْجٌ کی جمع ہے، سلف کی تفسیر میں بروج سے مراد بڑے بڑے ستارے لیے گئے ہیں۔ اور اسی مراد پر کلام کا نظم واضح ہے کہ بابرکت ہے وہ ذات جس نے آسمان میں بڑے بڑے ستارے اور سورج اور چاند بنائے۔ بعد کے مفسرین نےاس سے اہل نجوم کے مصطلحہ بروج مراد لے لیے۔ اور یہ بارہ برج ہیں۔ حمل، ثور، جوزاء، سرطان، اسد، سنبلہ، میزان، عقرب، قوس، جدی، دلو اور حوت۔ اور یہ برج سات بڑے سیاروں کی منزلیں ہیں۔ جن کے نام ہیں۔ مریخ، زہرہ، عطارد، قمر، شمس، مشتری اورزحل۔ یہ کواکب (سیارے) ان برجوں میں اس طرح اترتے ہیں، جیسے یہ ان کے لیے عالی شان محل ہیں (ایسرالتفاسیر)۔",
