      "en": "And [they are] those who do not testify to falsehood, and when they pass near ill speech, they pass by with dignity.",
      "footnotesUr": "[1] زور کے معنی جھوٹ کے ہیں۔ ہر باطل چیز بھی جھوٹ ہے، اس لیے جھوٹی گواہی سے لے کر کفر وشرک اور ہر طرح کی غلط چیزیں مثلاً لہوولعب، گانا اور دیگر بیہودہ جاہلانہ رسوم وافعال، سب اس میں شامل ہیں اورعبادالرحمٰن کی یہ صفت بھی ہےکہ وہ کسی بھی جھوٹ میں اور جھوٹ کی مجلسوں میں حاضر نہیں ہوتے۔\n[2] لَغْوٌ ہر وہ بات اور کام ہے ، جس میں شرعًا کوئی فائدہ نہیں۔ یعنی ایسے کاموں اور باتوں میں بھی وہ شرکت نہیں کرتے بلکہ خاموشی کے ساتھ عزت ووقار سے گزر جاتے ہیں۔",
